import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String> lines = new ArrayList<>();
        for (int i = 0; i < n; i++) lines.add(sc.nextLine());
        String summary = lines.remove(lines.size() - 1);

        int files = firstNumberBefore(summary, "file");
        int changed = firstNumberBefore(summary, "insertion") + firstNumberBefore(summary, "deletion");
        System.out.println(files <= 10 && changed <= 300 ? "REVIEWABLE" : "SPLIT");

        List<String[]> rows = new ArrayList<>();
        for (String line : lines) {
            int bar = line.lastIndexOf('|');
            String path = line.substring(0, bar).trim();
            String rest = line.substring(bar + 1).trim();
            int end = 0;
            while (end < rest.length() && Character.isDigit(rest.charAt(end))) end++;
            rows.add(new String[] {path, rest.substring(0, end)});
        }
        rows.sort(Comparator.comparingInt((String[] r) -> Integer.parseInt(r[1])).reversed()
                .thenComparing(r -> r[0]));
        for (String[] row : rows) System.out.println(row[0] + " " + row[1]);
    }

    /** 「3 files changed」のように、語の直前にある数を取り出す。無ければ0。 */
    static int firstNumberBefore(String summary, String word) {
        int at = summary.indexOf(word);
        if (at < 0) return 0;
        int end = at;
        while (end > 0 && !Character.isDigit(summary.charAt(end - 1))) end--;
        int start = end;
        while (start > 0 && Character.isDigit(summary.charAt(start - 1))) start--;
        return start == end ? 0 : Integer.parseInt(summary.substring(start, end));
    }
}

