import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int maxFiles = sc.nextInt();
        int maxLines = sc.nextInt();
        int n = sc.nextInt();
        int ok = 0;
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String module = sc.next();
            int files = sc.nextInt();
            int lines = sc.nextInt();
            int pinned = sc.nextInt();
            String status;
            if (files > maxFiles || lines > maxLines) {
                status = "SPLIT";
            } else if (pinned == 0) {
                status = "PIN";
            } else {
                status = "OK";
                ok++;
            }
            out.append(module).append(" ").append(status).append("\n");
        }
        System.out.print(out);
        System.out.println("ok=" + ok);
    }
}
